:root{color-scheme:dark;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;color:#dce5e5;background:#101616;--accent:#b9e878;--line:#2b3937;--muted:#8d9f9a}*{box-sizing:border-box}body{margin:0}header{display:flex;gap:14px;align-items:center;padding:22px 28px;border-bottom:1px solid var(--line);font-size:12px;letter-spacing:1px}.dot{width:8px;height:8px;background:var(--accent);border-radius:50%}#state{margin-left:auto;color:var(--accent)}main{display:grid;grid-template-columns:minmax(300px,0.8fr) minmax(450px,1.3fr);gap:20px;max-width:1550px;margin:auto;padding:26px}.panel{background:#151e1c;border:1px solid var(--line);border-radius:12px;padding:24px}.title{display:flex;align-items:center;justify-content:space-between;gap:16px}h1{font:500 25px system-ui;margin:0}h2{font:500 22px system-ui;margin:0}h3{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:1px}small{text-transform:none}.muted,.note,details{color:var(--muted);font-size:12px;line-height:1.7}.badge{font-size:11px;color:var(--accent);white-space:nowrap}label{display:block;font-size:11px;color:var(--muted);margin:20px 0 10px}select,textarea,button{font:inherit;border:1px solid #3b4c46;border-radius:5px;background:#111815;color:inherit;padding:10px}select{width:100%;font-size:12px}textarea{width:100%;height:320px;font-size:14px;line-height:1.7;resize:vertical;tab-size:4}button{cursor:pointer;font-size:12px;-webkit-user-select:none;user-select:none}button:hover{border-color:var(--accent)}button:disabled{opacity:.35;cursor:default}.primary{background:var(--accent);border-color:var(--accent);color:#192014;font-weight:700}.buttons{display:flex;gap:8px;margin:18px 0;flex-wrap:wrap}#seek{width:100%;accent-color:var(--accent)}.event{margin:15px 0;padding:12px;border-left:2px solid var(--accent);font-size:12px;background:#1e2a22}.inspect{display:grid;grid-template-columns:1fr 1fr;gap:20px;min-width:0}.inspect>div{min-width:0}pre,.values{font-size:12px;line-height:1.6;overflow:auto;max-height:240px;white-space:pre-wrap;overflow-wrap:anywhere}.source-line{display:block;padding:2px 6px}.active{background:#304226;color:#d0ff93;border-radius:3px}.value{padding:6px 8px;margin-bottom:4px;background:#101815;border:1px solid var(--line);border-radius:4px}.value span{color:var(--accent)}.output{min-height:60px;background:#0d1412;padding:12px;border:1px solid var(--line)}#message{color:#ffc68e;font-size:12px;line-height:1.7}footer{padding:5px 28px 25px;color:var(--muted);font-size:11px}footer span{float:right}summary{cursor:pointer}button:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:900px){main{grid-template-columns:1fr;padding:14px}.inspect{grid-template-columns:1fr 1fr}header .muted{display:none}footer span{float:none;display:block;margin-top:10px}}
main{grid-template-columns:minmax(270px,.7fr) minmax(450px,1.4fr)}.panel{min-width:0}.editor{grid-column:1;grid-row:1 / span 2}.map-panel{grid-column:2}.replay{grid-column:2}.map{overflow:auto;max-height:540px;min-height:160px;margin-top:16px;background-color:#101815;background-image:radial-gradient(#2b3937 1px,transparent 1px);background-size:18px 18px;border:1px solid var(--line);border-radius:6px}.map svg{display:block;height:auto;min-width:280px}.map .node{cursor:pointer}.map .node.executing path,.map .node.executing polygon{fill:#354b28;stroke:#b9e878;stroke-width:2.5}.map .node.selected path,.map .node.selected polygon,.map .node:focus path{stroke:#e7cf89;stroke-width:3}.map .edge.traversed path{stroke:#d0ff93;stroke-width:3}.map .edge.traversed polygon{fill:#d0ff93;stroke:#d0ff93}#frames{padding-top:12px;color:var(--accent)}.map-panel .buttons{margin-bottom:5px}@media(max-width:900px){main{grid-template-columns:1fr}.editor,.map-panel,.replay{grid-column:1;grid-row:auto}.map{max-height:420px}}
main{max-width:1900px;grid-template-columns:minmax(270px,330px) minmax(0,1fr);gap:18px;padding:20px}.editor{grid-row:1;align-self:start}.replay{grid-column:1 / -1}.xray{height:620px;position:relative;border:1px solid var(--line);border-radius:8px;overflow:hidden;margin-top:14px;background:#0d1413}.xray canvas{display:block;width:100%;height:100%;touch-action:none}.xray[data-error]::after{content:attr(data-error);position:absolute;bottom:12px;left:12px;color:#ffc68e}.block-controls{display:flex;align-items:center;gap:8px;margin-top:15px}.block-controls label{margin:0;white-space:nowrap}.block-controls select{flex:1;width:0;min-width:0}.block-controls button{white-space:nowrap}button[aria-pressed=true]{background:#304226;color:#d0ff93;border-color:#8ab463}.replay>.inspect{grid-template-columns:1fr 1fr}.map-panel .note{margin:8px 0;font-size:11px}.map-panel{padding:20px}.editor textarea{height:280px}.map{max-height:620px}[hidden]{display:none!important}@media(max-width:900px){main{grid-template-columns:1fr;padding:12px}.editor,.map-panel,.replay{grid-column:1}.xray{height:470px}.block-controls{flex-wrap:wrap}.block-controls select{flex-basis:65%}.block-controls button{flex:1}.editor textarea{height:220px}}
.opcode-panel{position:absolute;top:12px;right:12px;width:min(350px,calc(100% - 24px));border:1px solid #52705c;background:#101b18f2;box-shadow:0 8px 24px #0006;border-radius:6px;padding:10px;z-index:2}.opcode-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12px;color:#cde7b3}.opcode-heading button{padding:5px 8px;font-size:10px}.opcode-caption{font-size:10px;color:#9fb3a7;margin:8px 0;overflow-wrap:anywhere}.opcode-list{position:relative;max-height:220px;overflow:auto}.opcode-list button{display:block;width:100%;text-align:left;white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;line-height:1.4;padding:5px 7px;border:0;border-radius:0;border-left:2px solid transparent;background:#17261e}.opcode-list button:nth-child(even){background:#1b2d23}.opcode-list button.current{border-color:#cef38a;background:#354d26;color:#e0ffb2}.opcode-list button:disabled{opacity:.55}.opcode-panel button:focus-visible{outline-offset:-2px}@media(max-width:900px){.opcode-panel{top:8px;right:8px;width:min(300px,calc(100% - 16px));padding:8px}.opcode-list{max-height:125px}}

/* The world owns the viewport; tools float above it. */
body{height:100dvh;overflow:hidden}header{position:fixed;inset:0 0 auto;z-index:10;height:58px;padding:10px 18px;background:#101616e8;border:0}header button{padding:7px 10px}main{display:block;padding:0;margin:0;max-width:none}.map-panel{position:fixed;inset:0;padding:0;border:0;background:none;border-radius:0}.xray,.map{position:absolute;inset:0;margin:0;width:100%;height:100%;max-height:none;border:0;border-radius:0}.map{padding:120px 20px 130px}.map-title,.map-panel>p.note{display:none}.camera-controls{position:absolute;z-index:4;top:58px;left:18px;right:18px;margin:0!important;pointer-events:none}.camera-controls button{pointer-events:auto;padding:7px 10px;background:#15211deb}#map-status{position:absolute;left:20px;bottom:100px;z-index:3;pointer-events:none;background:#101616de;padding:4px 8px;max-width:calc(100% - 40px)}.transport{position:absolute;z-index:5;bottom:28px;left:50%;transform:translateX(-50%);width:min(540px,calc(100% - 32px));padding:8px 14px;background:#101b18ed;border:1px solid var(--line);border-radius:8px}.transport .buttons{margin:0 0 6px;justify-content:center}.transport button{padding:7px 12px}#scene-hint{position:absolute;bottom:5px;left:20px;margin:0;z-index:3;pointer-events:none;font-size:10px}.editor,.replay{position:fixed;z-index:6;top:106px;bottom:132px;overflow:auto;padding:18px;background:#151e1cf2;box-shadow:0 8px 30px #0005}.editor{left:18px;width:320px}.replay{right:18px;width:min(520px,calc(100% - 36px))}.editor h1{font-size:20px}.editor textarea{height:230px}.editor>p.muted{display:none}.opcode-panel{top:106px;right:18px}.block-controls{flex-wrap:wrap}.block-controls select{flex-basis:60%}footer{display:none}@media(max-width:900px){header{gap:8px;padding:8px;font-size:10px}header strong{font-size:10px}header button{padding:6px}.camera-controls{left:8px;right:8px;gap:4px}.camera-controls button{font-size:10px;padding:5px 7px}.editor,.replay{top:145px;bottom:135px;left:8px;right:8px;width:auto}.opcode-panel{top:145px;right:8px;width:260px}#map-status{font-size:9px;bottom:108px;left:8px}#scene-hint{display:none}.transport{bottom:16px}.replay>.inspect{grid-template-columns:1fr}}

#parse-panel{position:fixed;right:18px;top:106px;width:min(440px,calc(100% - 36px));z-index:5;background:#141e20f2;border:1px solid #526c7b;border-radius:8px;padding:16px;font-size:12px}#parse-status{margin:12px 0;color:#b9e878;overflow-wrap:anywhere}#parse-attempts{max-height:210px;font-size:11px;white-space:pre-wrap}#parse-seek{width:100%;accent-color:#b9e878}@media(max-width:900px){#parse-panel{top:180px;max-height:45vh;overflow:auto}}

.minimap{position:absolute;right:18px;bottom:18px;width:280px;padding:7px;background:#111d19ed;border:1px solid #4a6455;border-radius:6px;z-index:4}.minimap canvas{display:block!important;width:100%!important;height:128px!important;margin-top:0;cursor:crosshair;touch-action:none}.minimap canvas:focus-visible{outline:2px solid #b9e878}@media(max-width:900px){.minimap{width:180px;bottom:110px;right:8px}.minimap canvas{height:92px!important}}

/* Keep scene gestures and overlay scrolling inside the workspace. */
html,body{width:100%;height:100%;overflow:hidden;overscroll-behavior:none}
body{position:fixed;inset:0;height:100dvh}
.editor,.replay,.opcode-list,.map,#parse-panel{overscroll-behavior:contain}
.editor{max-width:calc(100% - 36px)}
header{min-width:0}header strong,header .muted,#state{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}header button{flex-shrink:0}
@media(max-width:900px){.editor{max-width:calc(100% - 16px)}}

/* Orbital observatory: restrained glass surfaces over a static starfield. */
:root{--control-outline:#48516a;--control-outline-hover:#7e91b3;--control-outline-active:#47818d;--accent:#65d4df;--line:#9c8fc540;--muted:#aaa0c5;color:#edf0f5;background:#0e0b19}
body{background:radial-gradient(ellipse at 18% 35%,#42428525,transparent 55%),radial-gradient(ellipse at 80% 65%,#18527320,transparent 50%),#0e0b19}
.xray{background-image:url('./stars.svg');background-color:transparent;background-size:1600px 1000px}
header{background:linear-gradient(#0a1022a8,#0a102240);border-bottom:1px solid #bed4ff12;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
.dot{box-shadow:0 0 14px #9ad6ff9c}
.editor,.replay,.opcode-panel,#parse-panel,.transport,.minimap{background:linear-gradient(135deg,#24203cbb,#14112488);border:1px solid #b2c9ff30;box-shadow:0 12px 45px #0003,inset 0 1px #e6edff12;backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}
textarea,select,button,.camera-controls button{background:#111a304f;border-color:var(--control-outline);color:#edf0f5}textarea{background:#090f234f}button:hover{background:#7899cc24;border-color:var(--control-outline-hover)}
.primary{background:#a4dfffcc;color:#101c34;border-color:#c6e9ff99;box-shadow:0 0 20px #7ebfff18}
button[aria-pressed=true]{background:#8ebeff20;color:#d0eaff;border-color:#b0dfff70}
.active,.event,.value,.output{background:#7e9ccc16;border-color:#8abaff30;color:#deecff}
.opcode-heading,#parse-status,.value span{color:#c4e5ff}.opcode-list button,.opcode-list button:nth-child(even){background:#19294150}.opcode-list button.current{background:#719fc033;border-color:#a4dfff;color:#e2f3ff}
#map-status{display:none}.map{background-color:#080e1a;background-image:radial-gradient(#667da738 1px,transparent 1px)}
#parse-seek{accent-color:var(--accent)}

.source-editor{position:relative;height:230px;overflow:hidden;border:1px solid #b4c9fa30;border-radius:5px;background:#090f234f}
.syntax-keyword{color:#cfacff}.syntax-string{color:#f1ca9d}.syntax-number{color:#8bded2}.syntax-comment{color:#8394ae}.syntax-builtin{color:#8ecfff}.syntax-operator{color:#b4c2de}.syntax-plain{color:#e2eaff}

.starfield{position:absolute;inset:0;pointer-events:none;overflow:hidden;background:radial-gradient(ellipse at 47% 43%,#bc358c38,transparent 43%),radial-gradient(ellipse at 24% 38%,#75509038,transparent 48%),radial-gradient(ellipse at 57% 52%,#456ca536,transparent 48%),radial-gradient(ellipse at 72% 66%,#724e8530,transparent 44%)}.starfield canvas{width:100%;height:100%}.xray>canvas{position:relative}.xray:has(.starfield){background-image:none}

/* Output stays anchored while inspection regions scroll independently. */
#inspector-panel{display:flex;flex-direction:column;overflow:hidden;gap:12px;min-height:0}
.inspector-main{flex:1 1 50%;min-height:0;overflow:auto;overscroll-behavior:contain}
#inspector-panel .inspector-values{flex:1 1 25%;min-height:70px;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;overflow:hidden}
.inspector-values>div,.inspector-output{display:flex;flex-direction:column;min-height:0;min-width:0}
.inspector-values h3,.inspector-output h3{flex:none;margin:0 0 8px}
#inspector-panel .values{flex:1;min-height:0;max-height:none;overflow:auto;overscroll-behavior:contain}
.inspector-output{flex:0 1 25%;min-height:80px}
#inspector-panel #stdout{flex:1;min-height:0;max-height:none;margin:0;overflow:auto;overscroll-behavior:contain}

/* Cyberdeck keycaps: violet surfaces, cyan legends, raspberry action keys. */
.primary,.playback-buttons .primary{background:#c92359;color:#fff0f6;border-color:#ee5788;box-shadow:none}
.primary:not(:disabled):hover,.playback-buttons .primary:not(:disabled):hover{background:#a51c49;border-color:#d84474}
button[aria-pressed=true]{background:#30206a;color:#65d4df;border-color:#7960aa}
.opcode-list button.current{background:#572042;border-color:#c92359;color:#fff0f6}
.opcode-heading,#parse-status{color:#65d4df}

/* Scene controls live with the minimap, leaving the world unobstructed. */
#minimap-tools{display:flex;flex-direction:column;gap:6px;margin-top:8px}
.minimap-tools-row{display:flex;gap:5px}
.minimap-tools-row button{flex:1;padding:6px 8px;font-size:11px}
.map-panel>#minimap-tools{position:absolute;right:18px;bottom:18px;z-index:6}
.editor,.replay,.opcode-panel{top:18px}
.editor{bottom:auto;max-height:calc(100dvh - 150px)}
#state{display:block;margin-top:8px;font-size:11px;color:var(--muted)}
@media(max-width:900px){.editor,.replay,.opcode-panel{top:8px}.minimap-tools-row button{padding:5px 3px;font-size:10px}}


/* Opcode navigation is part of the Inspector, not a scene overlay. */
#opcode-inspector .opcode-panel{position:static;width:100%;margin:14px 0;padding:0;border:0;border-radius:0;background:none;box-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none}
#opcode-inspector .opcode-list{max-height:200px;border:1px solid var(--line);border-radius:5px}
#opcode-inspector .opcode-list button:disabled{opacity:.8}
#inspector-panel details{margin:10px 0}
#inspector-panel .inspector-main{flex-basis:60%}
#inspector-panel .inspector-values{flex-basis:20%}

#source-view .source-line{width:100%;text-align:left;font:inherit;white-space:pre-wrap;border:1px solid transparent;border-radius:4px;background:transparent;color:inherit}
#source-view .source-line.active{background:#7e9ccc16}
#source-view .source-line:not(:disabled):hover{background:#7899cc24;border-color:#b4c9fa30}
#source-view .source-line:disabled{opacity:.6;cursor:default}

.navigation-controls{position:absolute;left:18px;bottom:18px;z-index:7;display:flex;align-items:center;gap:12px;max-width:calc(50% - 300px)}
.navigation-controls #scene-hint{position:static;display:block;margin:0;font-size:10px;line-height:1.5;min-width:0}
.navigation-selector{flex-shrink:0;display:flex;overflow:hidden;border:1px solid var(--control-outline);border-radius:7px;background:#101322b8}
.navigation-selector button{display:flex;align-items:center;justify-content:center;min-width:42px;height:34px;padding:6px 10px;border:0;border-right:1px solid var(--control-outline);border-radius:0;background:transparent;color:#a9a5bd;font-size:11px}
.navigation-selector button:last-child{border-right:0}
.navigation-selector button[aria-pressed="true"]{color:#65d4df;background:#65d4df12;box-shadow:none}
.navigation-selector button:hover{color:#65d4df;background:#65d4df24}
.navigation-selector button[aria-pressed="true"]:hover{color:#65d4df;background:#65d4df30}
.navigation-selector button:focus-visible{outline-offset:-3px}
.navigation-selector svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
@media(max-width:1100px){
 .navigation-controls{bottom:18px;max-width:none}
 .navigation-controls #scene-hint{position:absolute;left:0;bottom:calc(100% + 6px);width:calc(100vw - 36px)}
}
@media(max-width:900px){.navigation-controls{left:8px;bottom:8px}.navigation-controls #scene-hint{width:calc(100vw - 16px)}}

.editor>label[for="example"]{margin-top:0}

.program-toolbar{position:fixed;top:18px;left:18px;z-index:8;display:flex;align-items:center;gap:8px;max-width:calc(100% - 36px);flex-wrap:wrap}
.program-toolbar select{width:220px;max-width:100%;height:36px;padding:6px 10px;background:#101322d9;border-color:var(--control-outline)}
.program-toolbar button{height:36px;padding:6px 12px}
.program-toolbar #message{flex-basis:100%;max-width:500px;background:#101322d9;border-radius:5px;padding:6px 10px}
.program-toolbar #message:empty{display:none}
#editor-panel{top:64px;left:18px;bottom:auto;width:min(560px,calc(100% - 36px));max-height:calc(100dvh - 150px);z-index:8}
.editor-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}
.editor-heading label{margin:0}
.editor-heading button{padding:2px 8px;font-size:20px}
#editor-panel .source-editor{height:min(420px,calc(100dvh - 240px))}
#editor-panel #source,#editor-panel #source-highlight{height:100%;max-height:none}
@media(max-width:600px){.program-toolbar{top:8px;left:8px;gap:5px;max-width:calc(100% - 16px)}.program-toolbar select{width:160px}.program-toolbar button{padding:6px 9px}#editor-panel{top:94px;left:8px;width:calc(100% - 16px)}}

.minimap-tools-row button:has(svg){display:flex;align-items:center;justify-content:center}.minimap-tools-row svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}

.minimap-tools-row #zoom-out{margin-left:7%}

.minimap{top:var(--program-toolbar-bottom,64px);left:18px;right:auto;bottom:auto}
.program-toolbar #toggle-minimap{width:36px;padding:7px;display:flex;align-items:center;justify-content:center}
#toggle-minimap svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
#toggle-minimap[aria-pressed="true"]{color:#65d4df;border-color:var(--control-outline-active);background:#65d4df12}
#editor-panel{top:var(--program-toolbar-bottom,64px)}
@media(max-width:900px){.minimap{left:8px;top:var(--program-toolbar-bottom,54px);bottom:auto}}

.playback-controls{position:fixed;top:18px;right:18px;z-index:8;width:max-content;display:grid;gap:8px}
.playback-buttons{display:flex;gap:6px;justify-content:flex-end}
.playback-buttons button{height:36px;padding:6px 10px;display:flex;align-items:center;justify-content:center;background:#101322d9;border-color:var(--control-outline)}
.playback-buttons button:not(.primary):not(:disabled):hover{background:#7899cc24;border-color:var(--control-outline-hover)}
.playback-buttons svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.playback-buttons #reset{margin-right:12px}
.playback-buttons #toggle-inspector{margin-left:12px;gap:7px}
.playback-controls #seek{margin:0}
.playback-controls #counter{contain:inline-size;min-width:0;border:0;padding:0;background:none;color:var(--muted);font-size:11px;line-height:1.4;text-align:right;font-variant-numeric:tabular-nums}
#inspector-panel{top:var(--playback-bottom,88px);bottom:18px}
.program-toolbar{max-width:calc(100% - 340px)}
@media(max-width:900px){
 .program-toolbar{max-width:calc(100% - 16px)}
 .playback-controls{top:var(--program-toolbar-bottom,54px);right:8px;max-width:calc(100% - 16px)}
 .minimap{top:var(--playback-bottom,116px)}
 #editor-panel{top:var(--playback-bottom,116px)}
 #inspector-panel{top:var(--playback-bottom,116px);bottom:8px}
}

.playback-controls #seek{appearance:none;-webkit-appearance:none;height:20px;padding:0;border:0;background:transparent;cursor:pointer;--seek-progress:0%}
#seek::-webkit-slider-runnable-track{height:3px;border-radius:2px;background:linear-gradient(to right,#65d4df90 var(--seek-progress),#b2c9ff26 var(--seek-progress))}
#seek::-moz-range-track{height:3px;border-radius:2px;background:#b2c9ff26}
#seek::-moz-range-progress{height:3px;border-radius:2px;background:#65d4df90}
#seek::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:10px;height:10px;margin-top:-3.5px;border:1px solid #65d4df;border-radius:50%;background:#172635;box-shadow:0 0 0 2px #101322}
#seek::-moz-range-thumb{width:8px;height:8px;border:1px solid #65d4df;border-radius:50%;background:#172635;box-shadow:0 0 0 2px #101322}
#seek:enabled:hover::-webkit-slider-thumb,#seek:active::-webkit-slider-thumb{background:#65d4df}
#seek:enabled:hover::-moz-range-thumb,#seek:active::-moz-range-thumb{background:#65d4df}
#seek:focus-visible{outline:1px solid #65d4df80;outline-offset:3px;border-radius:4px}
#seek:disabled{opacity:.35;cursor:default}

.camera-mode-switch{display:flex;flex:2;min-width:0}
.camera-mode-switch button:first-child{border-radius:5px 0 0 5px}
.camera-mode-switch button:last-child{border-radius:0 5px 5px 0;margin-left:-1px}
.camera-mode-switch button[aria-pressed="true"]{position:relative;color:#65d4df;border-color:var(--control-outline-active);background:#65d4df12}


.playback-run-slot{display:grid}
.playback-run-slot button{grid-area:1 / 1}

.playback-run-slot #play:disabled{pointer-events:none}
#compile-hint{position:absolute;right:0;top:calc(100% + 8px);padding:8px 10px;border:1px solid #b2c9ff40;border-radius:5px;background:#101322ed;color:#edf0f5;font-size:11px;white-space:nowrap;pointer-events:none;opacity:0;transition:opacity .3s ease}
#compile-hint.visible{opacity:1}
@media(prefers-reduced-motion:reduce){#compile-hint{transition:none}}

/* Keep UI scrolling available, but route zoom exclusively to the scene. */
html,body{touch-action:pan-x pan-y}
.mobile-device .source-editor .cm-editor{font-size:16px}

.mobile-device{--hosting-clearance:52px}
.mobile-device .program-toolbar{top:max(8px,env(safe-area-inset-top));left:max(8px,env(safe-area-inset-left));gap:5px}
.mobile-device .minimap,.mobile-device #editor-panel{top:var(--program-toolbar-bottom,54px)}
@media(orientation:landscape){
 .mobile-device .program-toolbar{max-width:calc(100% - var(--playback-width,340px) - 32px - env(safe-area-inset-left) - env(safe-area-inset-right))}
 .mobile-device .program-toolbar select{width:clamp(110px,18vw,220px)}
 .mobile-device .program-toolbar button{padding:6px 9px}
 .mobile-device .playback-controls{top:max(8px,env(safe-area-inset-top));right:max(8px,env(safe-area-inset-right));bottom:auto}
 .mobile-device #editor-panel{max-height:calc(100dvh - var(--program-toolbar-bottom,54px) - 16px)}
}
@media(orientation:portrait){
 .mobile-device .program-toolbar{max-width:calc(100% - 16px - env(safe-area-inset-left) - env(safe-area-inset-right))}
 .mobile-device .playback-controls{top:auto;left:max(8px,env(safe-area-inset-left));right:auto;bottom:calc(var(--hosting-clearance) + max(8px,env(safe-area-inset-bottom)));max-width:calc(100% - 16px)}
 .mobile-device #inspector-panel{top:var(--program-toolbar-bottom,54px);bottom:calc(var(--playback-height,64px) + var(--hosting-clearance) + max(8px,env(safe-area-inset-bottom)) + 10px)}
 .mobile-device #editor-panel{max-height:calc(100dvh - var(--program-toolbar-bottom,54px) - var(--playback-height,64px) - var(--hosting-clearance) - env(safe-area-inset-bottom) - 28px)}
 .mobile-device #editor-panel .source-editor{height:min(420px,calc(100dvh - var(--program-toolbar-bottom,54px) - var(--playback-height,64px) - var(--hosting-clearance) - env(safe-area-inset-bottom) - 110px))}
 .mobile-device #compile-hint{top:auto;bottom:calc(100% + 8px)}
}

.hosting-banner{position:fixed;right:18px;bottom:18px;z-index:8;display:flex;align-items:center;justify-content:center;gap:.5em;height:36px;padding:0 18px;border:1px solid transparent;border-radius:5px;background:linear-gradient(#111322,#111322) padding-box,linear-gradient(110deg,#6672a5,#a78bfa,#59d9df,#6672a5) border-box;background-size:100% 100%,300% 100%;color:#e8e9f4;font-size:12px;text-decoration:none;white-space:nowrap;user-select:none;box-shadow:0 4px 18px #0004;animation:hosting-shimmer 5s ease-in-out infinite}
.hosting-brand{display:block;width:70px;height:auto}
.hosting-banner:hover{color:#fff;box-shadow:0 4px 22px #59d9df20}
.hosting-banner:focus-visible{outline:2px solid #59d9df;outline-offset:4px}
@keyframes hosting-shimmer{0%,100%{background-position:0 0,0% 50%}50%{background-position:0 0,100% 50%}}
#inspector-panel{bottom:76px}
.mobile-device .hosting-banner{left:max(8px,env(safe-area-inset-left));right:max(8px,env(safe-area-inset-right));bottom:max(8px,env(safe-area-inset-bottom));height:36px}
@media(orientation:landscape){.mobile-device #inspector-panel{bottom:calc(var(--hosting-clearance) + max(8px,env(safe-area-inset-bottom)))}}
@media(prefers-reduced-motion:reduce){.hosting-banner{animation:none}}

@media(max-width:900px){:root:not(.mobile-device) .hosting-banner{right:8px;bottom:8px}}
@media(max-width:380px){.navigation-controls{bottom:54px}}

#share-dialog,#about-dialog{width:min(480px,calc(100% - 32px));padding:20px;border:1px solid var(--control-outline);border-radius:10px;background:#171729;color:#edf0f5;box-shadow:0 20px 80px #0008}
#share-dialog::backdrop,#about-dialog::backdrop{background:#05071299;backdrop-filter:blur(4px)}
#share-dialog .editor-heading h2,#about-dialog .editor-heading h2{font-size:18px}
#share-dialog label{margin:16px 0 10px;line-height:1.6}
#share-url{width:100%;min-width:0;padding:10px;font:12px ui-monospace,SFMono-Regular,Consolas,monospace;color:inherit;background:#0d1020;border:1px solid var(--control-outline);border-radius:5px}
.share-link-row{display:flex;align-items:stretch;gap:8px;margin-bottom:12px}
.share-link-row #share-url{flex:1}
.share-link-row #copy-share{flex:none;white-space:nowrap;min-width:94px}
#share-status{font-size:12px;line-height:1.6;color:var(--muted);margin:0}
.mobile-device #share-url{font-size:16px}

#editor-error{margin:12px 0 0;padding:10px;border-left:2px solid #ee5788;background:#c923591a;color:#ffb3cb;font-size:12px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere}

.source-editor .cm-editor{height:100%}

#about-dialog{max-height:calc(100dvh - 32px);overflow:auto}
#about-dialog ul{padding-left:20px;margin:20px 0;line-height:1.7;font-size:13px}
#about-dialog li+li{margin-top:12px}
#about-dialog strong{color:#edf0f5}
#about-dialog li{color:var(--muted)}
#about-dialog a{color:#64d8e5;font-size:13px;line-height:1.6}
@media(max-width:400px){.playback-buttons button{padding-inline:8px}.playback-buttons #reset{margin-right:6px}.playback-buttons #toggle-inspector{margin-left:6px}}
@media(max-width:360px){.playback-buttons{gap:4px}.playback-buttons button{padding-inline:6px;font-size:11px}.playback-buttons svg{width:17px;height:17px}.playback-buttons #reset{margin-right:4px}.playback-buttons #toggle-inspector{margin-left:4px;gap:5px}}
